class Solution {
    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            sb.append(s.length()).append('#').append(s);
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        int i = 0;

        while (i < str.length()) {
            int j = i;
            while (str.charAt(j) != '#') {
                j++;
            }

            int len = Integer.parseInt(str.substring(i, j));
            String s = str.substring(j + 1, j + 1 + len);
            result.add(s);
            i = j + 1 + len;
        }

        return result;
    }
}

class Solution {
    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            for (char c : s.toCharArray()) {
                if (c == '/' || c == ':') {
                    sb.append('/');
                }
                sb.append(c);
            }
            sb.append(":");
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        int i = 0;

        while (i < str.length()) {
            if (str.charAt(i) == '/') {
                i++;
                current.append(str.charAt(i));
            } else if (str.charAt(i) == ':') {
                result.add(current.toString());
                current = new StringBuilder();
            } else {
                current.append(str.charAt(i));
            }
            i++;
        }

        return result;
    }
}

class Solution {
    public String encode(List<String> strs) {
        StringBuilder sb = new StringBuilder();
        for (String s : strs) {
            // Use 4-character fixed width for length
            sb.append(String.format("%4d", s.length())).append(s);
        }
        return sb.toString();
    }

    public List<String> decode(String str) {
        List<String> result = new ArrayList<>();
        int i = 0;

        while (i < str.length()) {
            int len = Integer.parseInt(str.substring(i, i + 4).trim());
            String s = str.substring(i + 4, i + 4 + len);
            result.add(s);
            i = i + 4 + len;
        }

        return result;
    }
}
